/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
  INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
  VALUES ('tb_products','Create',USER(),
    CONCAT('Producto creado. ID=',NEW.ID,', SKU=',NEW.SKU,', nombre=',NEW.name,
      ', descripción=',COALESCE(NEW.description,'NULL'),
      ', precio=',NEW.current_price,', stock=',NEW.current_stock,
      ', estado=',IF(COALESCE(NEW.status,b'0')=b'1','Activo','Inactivo')),
    CURRENT_TIMESTAMP,b'1');
END */;;
DELIMITER ;
