/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.SKU <=> NEW.SKU) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('SKU: [',OLD.SKU,'] -> [',NEW.SKU,']')); END IF;
  IF NOT (OLD.name <=> NEW.name) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('nombre: [',OLD.name,'] -> [',NEW.name,']')); END IF;
  IF NOT (OLD.description <=> NEW.description) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('descripción: [',COALESCE(OLD.description,'NULL'),'] -> [',COALESCE(NEW.description,'NULL'),']')); END IF;
  IF NOT (OLD.current_price <=> NEW.current_price) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('precio: [',OLD.current_price,'] -> [',NEW.current_price,']')); END IF;
  IF NOT (OLD.current_stock <=> NEW.current_stock) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('stock: [',OLD.current_stock,'] -> [',NEW.current_stock,']')); END IF;
  IF NOT (OLD.status <=> NEW.status) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('estado: [',IF(COALESCE(OLD.status,b'0')=b'1','Activo','Inactivo'),'] -> [',IF(COALESCE(NEW.status,b'0')=b'1','Activo','Inactivo'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tb_products','Update',USER(),CONCAT('Producto actualizado. ID=',NEW.ID,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
